#!/usr/bin/env node
// R346 (2026-10-07) — writes automation/r346.bat, the action of the "TRAIDS R346 1353" / "TRAIDS R346 1356" tasks.
// Written from this node FILE (never bash / node -e / PowerShell): explicit CRLF, every backslash from String.fromCharCode(92) — a
// 2026-10-07 .bat lost its backslash when it was written through a shell. Overwrites only its OWN earlier output (recognised by the
// "Generated by docs\r346\build-bat.cjs" line); refuses to overwrite any other file at that path.
//
// ONE LOG PER FIRE (2026-10-07 review, reproduced with two real cmd.exe processes): cmd opens a `>>` target without write sharing, so
// while the primary (13:53 task) still holds `>> r346.log`, the backup (13:56 task) cannot open it, node never starts, cmd exits, and
// nothing reaches the log — the backup and its "lock held" alert vanish exactly when they are needed. Each task passes its fire tag
// (1353 / 1356) as %1; the .bat accepts only those two tags (anything else = "manual") and writes automation\r346-<tag>.log.
"use strict";
const fs = require("fs"), path = require("path");
const BS = String.fromCharCode(92), CRLF = String.fromCharCode(13, 10);
const REPO = path.resolve(__dirname, "..", ".."), OUT = path.join(REPO, "automation", "r346.bat");
const MARK = "REM Generated by docs" + BS + "r346" + BS + "build-bat.cjs";
const LOG = "\"%~dp0r346-%FIRE%.log\"";
const lines = [
  "@echo off",
  "REM TRAIDS R346 decision (2026-10-07, operator: \"paper r328\"). Run by the \"TRAIDS R346 1353\" task (13:53 MT = 15:53 ET on weekdays,",
  "REM local-time trigger, follows DST) and its backup \"TRAIDS R346 1356\" (15:56 ET), plus 10:53 / 10:56 MT on NYSE early-close dates.",
  "REM The runner refuses outside [close-7, close-1) ET on Alpaca's calendar, waits until close-5:00, decides ONCE a day from live Schwab",
  "REM quotes and sends DAY market orders to the Alpaca PAPER main account (hard guard: no POST outside close-10..close-1 ET or to a",
  "REM non-paper host). The backup fire sends nothing already sent. Fills, official bars and the shadow are the close chain's (--after-close).",
  "REM The first argument is the fire tag from the task (1353 or 1356; anything else = manual). One log per fire, automation" + BS + "r346-TAG.log:",
  "REM cmd opens an append-redirect target without write sharing, so two fires on one log would keep the backup from starting while the primary runs.",
  MARK + "; never edit this file through PowerShell (encoding).",
  "cd /d \"%~dp0..\"",
  "set \"FIRE=manual\"",
  "if \"%~1\"==\"1353\" set \"FIRE=1353\"",
  "if \"%~1\"==\"1356\" set \"FIRE=1356\"",
  "echo [%date% %time%] r346 decide %FIRE% >> " + LOG,
  "node backend" + BS + "r346-rsi2-etf-forward.js --decide --live --by task%FIRE% >> " + LOG + " 2>&1",
];
const text = lines.join(CRLF) + CRLF;
// proofs on the output
const must = ["cd /d \"%~dp0..\"", "node backend" + BS + "r346-rsi2-etf-forward.js --decide --live --by task%FIRE%", ">> \"%~dp0r346-%FIRE%.log\" 2>&1",
  "if \"%~1\"==\"1353\" set \"FIRE=1353\"", "if \"%~1\"==\"1356\" set \"FIRE=1356\"", "set \"FIRE=manual\"", MARK];
for (const m of must) if (!text.includes(m)) throw new Error("missing in the .bat: " + m);
if (/r346\.log/.test(text)) throw new Error("the shared r346.log is back in the .bat");
for (const l of lines) if (/^REM /.test(l) && /[<>|&%^]/.test(l)) throw new Error("a cmd metacharacter in a REM line: " + l);
if (/[^\r]\n/.test(text)) throw new Error("a bare LF slipped in");
if (!Buffer.from(text, "latin1").includes(Buffer.from([0x5c, 0x72, 0x33, 0x34, 0x36]))) throw new Error("the backslash before r346 is missing");
if (/[^\x00-\x7f]/.test(text)) throw new Error("non-ASCII in the .bat");
if (fs.existsSync(OUT)) {
  const cur = fs.readFileSync(OUT, "latin1");
  if (cur === text) { console.log("automation/r346.bat already identical — unchanged"); process.exit(0); }
  if (!cur.includes(MARK)) throw new Error("automation/r346.bat exists, differs and is not this generator's output — refusing to overwrite");
  console.log("automation/r346.bat is this generator's earlier output — replacing it");
}
fs.writeFileSync(OUT, Buffer.from(text, "latin1"));
const back = fs.readFileSync(OUT, "latin1"); if (back !== text) throw new Error("read-back differs from what was written");
console.log(`wrote ${OUT} (${text.length} bytes, ${lines.length} lines, CRLF, ASCII; read back identical)`);
